package com.clavis.reader;
import android.content.*;import android.widget.*;import android.view.*;import java.util.*;import org.json.JSONArray;
/** Topic choices stay local and apply to both publishers and individual stories. */
final class FeedTopics {
 static final LinkedHashMap<String,String> WORDS=new LinkedHashMap<>();
 static{WORDS.put("Medical","health|medicin|clinical|patient|disease|cancer|hospital|surgery|vaccine|diabet|cardio|mental health|psychiatr|public health|स्वास्थ्य|चिकित्सा|रोग|अस्पताल|मधुमेह|हृदय|कैंसर|टीका");WORDS.put("Technology","software|computer|digital|artificial intelligence|cyber|android|linux|internet|technology|machine learning|तकनीक|प्रौद्योगिकी|कंप्यूटर");WORDS.put("Science","science|scientist|research|discovery|experiment|विज्ञान|वैज्ञानिक|अनुसंधान");WORDS.put("Environment","climate|environment|warming|ecolog|biodiversity|conservation|pollution|renewable|sustainab|पर्यावरण|जलवायु|प्रदूषण");WORDS.put("Business","business|econom|finance|market|trade|investment|inflation");WORDS.put("Politics","politic|election|government|parliament|congress|democra|policy");WORDS.put("India","india|indian|delhi|mumbai|bengaluru|chennai");WORDS.put("World","international|global|world|diploma");WORDS.put("Culture","culture|art |artists|literature|music|cinema|history|museum");WORDS.put("Education","education|school|teaching|student|learning|university");WORDS.put("Social sciences","sociolog|psycholog|society|inequality|humanities|social");WORDS.put("Engineering","engineering|robot|manufactur|materials|infrastructure");WORDS.put("Mathematics","mathematic|statistics|algorithm|geometry");WORDS.put("Physics","physics|quantum|particle|relativity");WORDS.put("Chemistry","chemistry|chemical|molecule|catalys");WORDS.put("Biology","biology|genom|genetic|organism|microb|plant|protein");WORDS.put("Space","space|astronom|planet|galaxy|cosmos|nasa|telescope");}
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("feed_topics",0);}
 static Set<String> selected(Context c,String kind){return new HashSet<>(prefs(c).getStringSet(kind,Collections.emptySet()));}
 static boolean item(Context c,FeedStore.Feed feed,FeedStore.Item item){return item(selected(c,feed.kind),feed,item);}
 static boolean item(Set<String> topics,FeedStore.Feed feed,FeedStore.Item item){if(topics.isEmpty()||feed.kind.equals("Podcasts"))return true;String text=(item.title+" "+item.description).toLowerCase(Locale.ROOT);for(String topic:topics)if(feed.tags.contains(topic)||matches(text,WORDS.get(topic)))return true;return false;}
 static boolean matches(String text,String terms){if(terms==null)return false;for(String term:terms.split("\\|"))if(text.contains(term))return true;return false;}
 static boolean source(Context c,FeedStore.Feed feed){Set<String> topics=selected(c,feed.kind);if(topics.isEmpty()||feed.kind.equals("Podcasts"))return true;for(String tag:feed.tags)if(topics.contains(tag))return true;for(FeedStore.Item item:feed.items)if(item(topics,feed,item))return true;return false;}
 static ArrayList<FeedStore.Feed> sources(Context c,List<FeedStore.Feed> feeds){ArrayList<FeedStore.Feed> filtered=new ArrayList<>();for(FeedStore.Feed feed:feeds)if(source(c,feed))filtered.add(feed);return filtered;}
 static boolean latest(Context c,String kind){android.content.SharedPreferences p=prefs(c);if(!p.getBoolean("popular_default_v2_"+kind,false)){p.edit().putBoolean("latest_"+kind,false).putBoolean("popular_default_v2_"+kind,true).apply();return false;}return p.getBoolean("latest_"+kind,false);}
 static ArrayList<String> recent(Context c,String kind){ArrayList<String> result=new ArrayList<>();try{JSONArray data=new JSONArray(prefs(c).getString("recent_"+kind,"[]"));for(int n=0;n<data.length();n++){String tag=data.getString(n);if(WORDS.containsKey(tag)&&!result.contains(tag))result.add(tag);}}catch(Exception ignored){}for(String tag:WORDS.keySet())if(selected(c,kind).contains(tag)&&!result.contains(tag))result.add(tag);return result;}
 static void remember(List<String> history,String tag){history.remove(tag);history.add(0,tag);}
 static void save(Context c,String kind,Set<String> chosen,List<String> history){prefs(c).edit().putStringSet(kind,new HashSet<>(chosen)).putString("recent_"+kind,new JSONArray(history).toString()).apply();}
 static ArrayList<String> quickTags(Context c,String kind){ArrayList<String> choices=recent(c,kind);for(String tag:WORDS.keySet())if(choices.size()<2&&!choices.contains(tag))choices.add(tag);return new ArrayList<>(choices.subList(0,Math.min(2,choices.size())));}
 static ArrayList<String> rowCandidates(Context c,String kind){ArrayList<String> history=recent(c,kind),result=new ArrayList<>();Set<String> chosen=selected(c,kind);for(String tag:history)if(chosen.contains(tag))result.add(tag);for(String tag:history)if(!result.contains(tag))result.add(tag);for(String tag:WORDS.keySet())if(!result.contains(tag))result.add(tag);return result;}
 static ArrayList<String> fitTags(Context c,String kind,int available,java.util.function.ToIntFunction<String> width){ArrayList<String> result=new ArrayList<>();for(String tag:rowCandidates(c,kind)){int size=width.applyAsInt(tag);if(size<=available){result.add(tag);available-=size;}}return result;}
 static String overflowLabel(Set<String> chosen,List<String> visible){Set<String> hidden=new HashSet<>(chosen);hidden.removeAll(visible);return hidden.isEmpty()?"Show more":"+"+hidden.size()+" more";}
 static void sort(MainActivity a,String kind,boolean sources){if(sources){new AppDialog.Builder(a).setTitle("Sort by").setSingleChoiceItems(new String[]{"Alphabetical (A–Z)","Date added (newest first)"},prefs(a).getInt("source_sort_"+kind,0),(dialog,index)->{prefs(a).edit().putInt("source_sort_"+kind,index).apply();dialog.dismiss();FeedScreens.show(a,kind,true);}).setNegativeButton("Cancel",null).show();return;}new AppDialog.Builder(a).setTitle("Sort by").setSingleChoiceItems(new String[]{"Popular","Latest"},latest(a,kind)?1:0,(dialog,index)->{prefs(a).edit().putBoolean("latest_"+kind,index==1).putBoolean("popular_default_v2_"+kind,true).apply();dialog.dismiss();FeedScreens.show(a,kind,sources);}).setNegativeButton("Cancel",null).show();}
 static TextView chip(MainActivity a,String label,boolean on,Runnable action){TextView view=a.button(label,action);view.setTextSize(11);view.setMinHeight(0);view.setMinimumHeight(0);view.setMinWidth(0);view.setMinimumWidth(0);view.setIncludeFontPadding(false);view.setSingleLine();view.setEllipsize(android.text.TextUtils.TruncateAt.END);view.setGravity(Gravity.CENTER);view.setPadding(a.dp(8),a.dp(3),a.dp(8),a.dp(3));view.setSelected(on);view.setContentDescription(label+" tag"+(on?", selected":""));int[] colors={0xffbc691a,0xff2878d0,0xff8056d9,0xff278946,0xffbd4040};int tint=colors[Math.floorMod((label.startsWith("+")?"Show more":label).hashCode(),colors.length)];android.graphics.drawable.GradientDrawable background=UiStyle.surface(a,"News",8);background.setColor(androidx.core.graphics.ColorUtils.blendARGB(AppTheme.dark?AppTheme.surface:0xffffffff,tint,on?(AppTheme.dark?.32f:.17f):(AppTheme.dark?.16f:.08f)));view.setBackground(background);view.setTextColor(AppTheme.dark?androidx.core.graphics.ColorUtils.blendARGB(tint,0xffffffff,.5f):tint);view.setTypeface(a.serif,on?android.graphics.Typeface.BOLD:android.graphics.Typeface.NORMAL);return view;}
 static void tags(MainActivity a,String kind,boolean sources){if(kind.equals("Podcasts"))return;LinearLayout row=a.row();row.setTag("feed-tag-strip");row.setPadding(a.dp(12),a.dp(2),a.dp(12),a.dp(6));Set<String> chosen=selected(a,kind);
  TextView all=chip(a,"All",chosen.isEmpty(),()->{save(a,kind,Collections.emptySet(),recent(a,kind));FeedScreens.show(a,kind,sources);});LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-2,a.dp(28));ap.rightMargin=a.dp(6);row.addView(all,ap);
  android.text.TextPaint measure=new android.text.TextPaint();measure.setTextSize(11*a.getResources().getDisplayMetrics().scaledDensity);measure.setTypeface(android.graphics.Typeface.create(a.serif,android.graphics.Typeface.BOLD));int width=a.getResources().getDisplayMetrics().widthPixels-a.dp(24);int reserved=Math.round(measure.measureText("All")+Math.max(measure.measureText("Show more"),measure.measureText("+17 more")))+a.dp(38);ArrayList<String> visible=fitTags(a,kind,Math.max(0,width-reserved),tag->Math.round(measure.measureText(tag))+a.dp(22));
  for(String tag:visible){TextView button=chip(a,tag,chosen.contains(tag),()->{Set<String> next=selected(a,kind);ArrayList<String> history=recent(a,kind);if(!next.remove(tag)){next.add(tag);remember(history,tag);}save(a,kind,next,history);FeedScreens.show(a,kind,sources);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,a.dp(28));p.rightMargin=a.dp(6);row.addView(button,p);}
  String moreLabel=overflowLabel(chosen,visible);TextView more=chip(a,moreLabel,!moreLabel.equals("Show more"),()->choose(a,kind,sources));more.setContentDescription("Show more tags. "+chosen.size()+" selected");row.addView(more,new LinearLayout.LayoutParams(-2,a.dp(28)));a.root.addView(row,1,new LinearLayout.LayoutParams(-1,a.dp(36)));
 }
 static void choose(MainActivity a,String kind,boolean sources){String[] labels=WORDS.keySet().toArray(new String[0]);Set<String> chosen=selected(a,kind);ArrayList<String> history=recent(a,kind);boolean[] checked=new boolean[labels.length];for(int n=0;n<labels.length;n++)checked[n]=chosen.contains(labels[n]);new AppDialog.Builder(a).setTitle("Select tags").setMultiChoiceItems(labels,checked,(d,n,on)->{if(on){chosen.add(labels[n]);remember(history,labels[n]);}else chosen.remove(labels[n]);}).setPositiveButton("Apply",(d,n)->{save(a,kind,chosen,history);FeedScreens.show(a,kind,sources);}).setNeutralButton("All",(d,n)->{save(a,kind,Collections.emptySet(),history);FeedScreens.show(a,kind,sources);}).setNegativeButton("Cancel",null).show();}
}
